  description: "Body of handled errors (validation 400, identity 401, rec-engine 503). Bare 404s and JWT auth failures have NO body."
  properties:
    error: { type: string }
RegisterIdentityRequest:
  type: object
  required: [publicKey, signature]
  properties:
    publicKey: { type: string, description: "lowercase hex, raw 32-byte Ed25519 key (64 chars)" }
    signature: { type: string, description: "lowercase hex Ed25519 sig (128 chars) over UTF-8 `viewrr:register`" }
    displayName: { type: string, nullable: true, description: "optional cosmetic petname, set once at first register" }
ChallengeResponse:
  type: object
  properties:
    challenge: { type: string, description: single-use hex nonce }
VerifyIdentityRequest:
  type: object
  required: [publicKey, challenge, signature]
  properties:
    publicKey: { type: string, description: "lowercase hex, raw 32-byte Ed25519 key" }
    challenge: { type: string, description: "the nonce from GET /identity/challenge" }
    signature: { type: string, description: "lowercase hex Ed25519 sig over the UTF-8 bytes of `challenge`" }
AccountView:
  type: object
  description: Returned by /identity/register — the account, no secret material.
  properties:
    accountId: { type: string, format: uuid }
    publicKey: { type: string }
    displayName: { type: string, nullable: true }
TokenPair:
  type: object
  description: "Returned by /identity/verify. accessToken = HS256 JWT (15-min TTL, sub=accountId). refreshToken issued but not yet redeemable — re-run challenge→verify on expiry."
  properties:
    accessToken: { type: string }
    refreshToken: { type: string }

